package com.muthumol.player.dummy;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.net.Uri;import java.util.*;
/** First observation establishes a baseline; only later newly posted titles notify. */
final class ContentAlerts {
 static void notice(Context c,String kind,String text,int id){if(!c.getSharedPreferences("alerts",0).getBoolean(kind,true))return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String channel="tgstream-"+kind;if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(channel,kind,NotificationManager.IMPORTANCE_DEFAULT));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,channel):new Notification.Builder(c);PendingIntent open=PendingIntent.getActivity(c,id,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify(id,b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("TG stream").setContentText(text).setContentIntent(open).setAutoCancel(true).build());}
 static void observe(Context c,List<Movie> source){SharedPreferences p=c.getSharedPreferences("content-seen",0);Map<Long,Long> latest=new HashMap<>();Set<String> notified=new HashSet<>();SharedPreferences.Editor seen=p.edit();for(Movie m:source){if(!LibraryContent.visible(c,m))continue;latest.put(m.chatId,Math.max(latest.getOrDefault(m.chatId,0L),m.date));long before=p.getLong("chat:"+m.chatId,0);String titleKey="title:"+VideoCopies.key(m);if(before>0&&m.date>before&&!p.contains(titleKey)&&notified.add(titleKey))notice(c,"new-content","New · "+MediaTitle.parse(m.title).display(),Math.abs(VideoCopies.key(m).hashCode()));seen.putBoolean(titleKey,true);}seen.apply();SharedPreferences.Editor e=p.edit();for(Map.Entry<Long,Long> item:latest.entrySet())e.putLong("chat:"+item.getKey(),Math.max(p.getLong("chat:"+item.getKey(),0),item.getValue()));e.apply();long free=c.getFilesDir().getUsableSpace();if(free<128L*1048576&&System.currentTimeMillis()-p.getLong("low-space",0)>86400000){notice(c,"storage","Low storage · "+MainActivity.size(free)+" free",2002);p.edit().putLong("low-space",System.currentTimeMillis()).apply();}TvLauncher.publish(c,source);}
 static void settings(MainActivity a){SharedPreferences p=a.getSharedPreferences("alerts",0);if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},707);Ui.menu(a,"Notifications / TV launcher",new String[]{"New movies / episodes · "+p.getBoolean("new-content",true),"Low storage · "+p.getBoolean("storage",true),"Saved-copy cleanup · "+p.getBoolean("downloads",true),"TV launcher row · "+p.getBoolean("launcher",true)},n->{String key=new String[]{"new-content","storage","downloads","launcher"}[n];p.edit().putBoolean(key,!p.getBoolean(key,true)).apply();if(n==3)TvLauncher.publish(a,a.libraryMovies());});}
}
